    if not isinstance(text, str):
        raise MoneyError("invalid amount '%s': not text" % (text,))
    m = _AMOUNT.fullmatch(text)
    if m is None:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.group(1), m.group(2), m.group(3)
    if frac is not None and len(frac) > exponent:
        raise MoneyError("invalid amount '%s': %s has %d decimals" % (text, cur, exponent))
    minor = int(whole + (frac or "").ljust(exponent, "0"))
    return -minor if sign == "-" else minor


class Money:
    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency_code):
        if not _is_int(minor):
            raise MoneyError("minor units must be an integer, not %r" % (minor,))
        currency(currency_code)
        object.__setattr__(self, "_minor", minor)
        object.__setattr__(self, "_currency", currency_code)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    minor = property(lambda self: self._minor)
    currency = property(lambda self: self._currency)
    exponent = property(lambda self: CURRENCIES[self._currency].exponent)

    @classmethod
    def zero(cls, cur):
        return cls(0, cur)

    @classmethod
    def of(cls, text, cur):
        return cls(parse_amount(text, cur), cur)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money '%s': not text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise MoneyError("invalid money '%s': write an amount, one space and a currency" % text)
        return cls.of(parts[0], parts[1])

    def amount_str(self):
        return format_minor(self._minor, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self._currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self._minor, self._currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._minor == other._minor and self._currency == other._currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._minor, self._currency))

    def _same(self, other, verb):
        if self._currency != other._currency:
            raise MoneyError("cannot %s %s and %s: different currencies"
                             % (verb, self._currency, other._currency))

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self._minor + other._minor, self._currency)

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self._minor - other._minor, self._currency)

    def __neg__(self):
        return Money(-self._minor, self._currency)

    def __abs__(self):
        return Money(abs(self._minor), self._currency)

    def __mul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    __rmul__ = __mul__

    def _cmp(self, other, op):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "compare")
        return op(self._minor, other._minor)

    def __lt__(self, other):
        return self._cmp(other, lambda a, b: a < b)

    def __le__(self, other):
        return self._cmp(other, lambda a, b: a <= b)

    def __gt__(self, other):
        return self._cmp(other, lambda a, b: a > b)

    def __ge__(self, other):
        return self._cmp(other, lambda a, b: a >= b)

    def is_zero(self):
        return self._minor == 0

    def sign(self):
        return (self._minor > 0) - (self._minor < 0)

    def scale(self, num, den=1):
        if not _is_int(num) or not _is_int(den):
            raise MoneyError("scale needs integers")
        if den == 0:
            raise MoneyError("scale: the denominator may not be zero")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self._minor * num, den), self._currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)):
            raise MoneyError("weights must be a list of integers")
        weights = list(weights)
        if not weights or not all(_is_int(w) and w >= 0 for w in weights):
            raise MoneyError("weights must be non-negative integers, at least one of them")
        total = sum(weights)
        if total <= 0:
            raise MoneyError("weights must add up to more than zero")
        amount = abs(self._minor)
        shares = [amount * w // total for w in weights]
        rems = [amount * w % total for w in weights]
        left = amount - sum(shares)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            shares[i] += 1
        if self._minor < 0:
            shares = [-s for s in shares]
        return [Money(s, self._currency) for s in shares]
"""Currencies and exact exchange rates."""
import re
from dataclasses import dataclass
from datetime import date, datetime
from fractions import Fraction

from tallybook.errors import ValidationError


class CurrencyError(ValidationError):
    pass


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


_TABLE = [
    ("USD", 2, "US Dollar", "$"),
    ("EUR", 2, "Euro", "€"),
    ("GBP", 2, "British Pound", "£"),
    ("JPY", 0, "Japanese Yen", "¥"),
    ("CHF", 2, "Swiss Franc", "CHF"),
    ("CAD", 2, "Canadian Dollar", "CA$"),
    ("AUD", 2, "Australian Dollar", "A$"),
    ("KWD", 3, "Kuwaiti Dinar", "KD"),
    ("SEK", 2, "Swedish Krona", "kr"),
    ("INR", 2, "Indian Rupee", "₹"),
    ("NZD", 2, "New Zealand Dollar", "NZ$"),
    ("NOK", 2, "Norwegian Krone", "kr"),
    ("KRW", 0, "South Korean Won", "₩"),
    ("BHD", 3, "Bahraini Dinar", "BD"),
    ("CNY", 2, "Chinese Yuan", "CN¥"),
    ("MXN", 2, "Mexican Peso", "MX$"),
]

CURRENCIES = {c[0]: Currency(*c) for c in _TABLE}


def currency(code):
    if isinstance(code, str) and code in CURRENCIES:
        return CURRENCIES[code]
    raise CurrencyError("unknown currency '%s'" % (code,))


def is_date(value):
    return isinstance(value, date) and not isinstance(value, datetime)


def _day(on):
    if not is_date(on):
        raise CurrencyError("not a date: %r" % (on,))
    return on.isoformat() if on.year >= 1000 else "%04d-%02d-%02d" % (on.year, on.month, on.day)


_RATE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


class RateTable:
    def __init__(self):
        self._rates = {}  # (src, dst) -> {date: Fraction}

    def _check(self, src, dst):
        currency(src)
        currency(dst)

    def set(self, src, dst, rate_text, on):
        self._check(src, dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        if not isinstance(rate_text, str) or not _RATE.fullmatch(rate_text):
            raise CurrencyError("invalid rate '%s'" % (rate_text,))
        rate = Fraction(rate_text)
        if rate <= 0:
            raise CurrencyError("invalid rate '%s': must be positive" % rate_text)
        _day(on)
        self._rates.setdefault((src, dst), {})[on] = rate

    def _latest(self, src, dst, on):
        best = None
        for d in self._rates.get((src, dst), ()):
            if d <= on and (best is None or d > best):
                best = d
        return None if best is None else self._rates[(src, dst)][best]

    def rate(self, src, dst, on):
        self._check(src, dst)
        day = _day(on)
        if src == dst:
            return Fraction(1)
        direct = self._latest(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._latest(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, day))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("cannot convert %r: not an amount of money" % (money,))
        currency(dst)
        _day(on)
        if money.currency == dst:
            return money
        rate = self.rate(money.currency, dst, on)
        diff = CURRENCIES[dst].exponent - CURRENCIES[money.currency].exponent
        num = money.minor * rate.numerator
        den = rate.denominator
        if diff >= 0:
            num *= 10 ** diff
        else:
            den *= 10 ** (-diff)
        return Money(round_div(num, den), dst)

    def entries(self):
        out = []
        for (src, dst), days in self._rates.items():
            for d, r in days.items():
                out.append((src, dst, d, r))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        self._check(src, dst)
        day = _day(on)
        days = self._rates.get((src, dst))
        if not days or on not in days:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, day))
        del days[on]
        if not days:
            del self._rates[(src, dst)]

"""Strict dates, month arithmetic and periods."""
import re
from datetime import date, datetime, timedelta

from tallybook.errors import ParseError


class DateError(ParseError):
    pass


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date '%s': not text" % (text,))
    m = _DATE.fullmatch(text)
    if m is None:
        raise DateError("invalid date '%s': write YYYY-MM-DD" % text)
    try:
        return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text)


def format_date(d):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("year and month must be integers")
    if not 1 <= year <= 9999 or not 1 <= month <= 12:
        raise DateError("no such month: %s-%s" % (year, month))
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(d, n):
    if not _is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not _is_int(n):
        raise DateError("months must be a whole number, not %r" % (n,))
    total = d.year * 12 + (d.month - 1) + n
    year, month = divmod(total, 12)
    month += 1
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    return date(year, month, min(d.day, last_day(year, month)))


_YEAR = re.compile(r"([0-9]{4})")
_MONTH = re.compile(r"([0-9]{4})-([0-9]{2})")
_QUARTER = re.compile(r"([0-9]{4})-Q([1-4])")
_RANGE = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})")


class Period:
    __slots__ = ("_start", "_end")

    def __init__(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise DateError("a period needs two dates, not %r and %r" % (start, end))
        if end < start:
            raise DateError("empty period: %s ends before %s" % (format_date(end), format_date(start)))
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)

    def __setattr__(self, name, value):
        raise AttributeError("Period is immutable")

    start = property(lambda self: self._start)
    end = property(lambda self: self._end)

    def __eq__(self, other):
        return isinstance(other, Period) and self._start == other._start and self._end == other._end

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._start, self._end))

    def __repr__(self):
        return "Period(%r, %r)" % (self._start, self._end)

    def __str__(self):
        return self.label

    def contains(self, d):
        if not _is_date(d):
            raise DateError("not a date: %r" % (d,))
        return self._start <= d <= self._end

    @property
    def days(self):
        return (self._end - self._start).days + 1

    @property
    def label(self):
        s, e = self._start, self._end
        if s.day == 1 and e.year == s.year:
            if s.month == 1 and e.month == 12 and e.day == 31:
                return "%04d" % s.year
            if s.month in (1, 4, 7, 10) and e.month == s.month + 2 and e.day == last_day(e.year, e.month):
                return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
            if e.month == s.month and e.day == last_day(s.year, s.month):
                return "%04d-%02d" % (s.year, s.month)
        return "%s..%s" % (format_date(s), format_date(e))

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period '%s': not text" % (text,))
        try:
            m = _YEAR.fullmatch(text)
            if m:
                y = int(text)
                return cls(date(y, 1, 1), date(y, 12, 31))
            m = _MONTH.fullmatch(text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                return cls(date(y, mo, 1), date(y, mo, last_day(y, mo)))
            m = _QUARTER.fullmatch(text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                first = (q - 1) * 3 + 1
                return cls(date(y, first, 1), date(y, first + 2, last_day(y, first + 2)))
            m = _RANGE.fullmatch(text)
            if m:
                return cls(parse_date(m.group(1)), parse_date(m.group(2)))
        except (DateError, ValueError) as err:
            raise DateError("invalid period '%s': %s" % (text, err))
        raise DateError("invalid period '%s': write 2024, 2024-03, 2024-Q1 or 2024-03-01..2024-03-31" % text)

    def next(self):
        s, e = self._start, self._end
        try:
            label = self.label
            if len(label) == 4:
                return Period(date(s.year + 1, 1, 1), date(s.year + 1, 12, 31))
            if len(label) == 7 and label[5] == "Q":
                first = s.month + 3
                year = s.year
                if first > 12:
                    first, year = 1, year + 1
                return Period(date(year, first, 1), date(year, first + 2, last_day(year, first + 2)))
            if len(label) == 7:
                nxt = add_months(s, 1)
                return Period(nxt, date(nxt.year, nxt.month, last_day(nxt.year, nxt.month)))
            start = e + timedelta(days=1)
            return Period(start, start + timedelta(days=self.days - 1))
        except (ValueError, OverflowError):
            raise DateError("no period after %s" % self.label)


_STEPS = ("week", "month", "quarter", "year")


def _containing(d, step):
    if step == "week":
        monday = d - timedelta(days=d.weekday())
        return Period(monday, monday + timedelta(days=6))
    if step == "month":
        return Period(date(d.year, d.month, 1), date(d.year, d.month, last_day(d.year, d.month)))
    if step == "quarter":
        first = (d.month - 1) // 3 * 3 + 1
        return Period(date(d.year, first, 1), date(d.year, first + 2, last_day(d.year, first + 2)))
    return Period(date(d.year, 1, 1), date(d.year, 12, 31))


def periods(start, end, step):
    if not _is_date(start) or not _is_date(end):
        raise DateError("periods needs two dates")
    if not isinstance(step, str) or step not in _STEPS:
        raise DateError("unknown step '%s': use week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("%s is before %s" % (format_date(end), format_date(start)))
    try:
        p = _containing(start, step)
        out = [p]
        while p.end < end:
            p = p.next()
            out.append(p)
    except (ValueError, OverflowError):
        raise DateError("periods run past the end of the calendar")
    return out
"""Plain data records shared by every module."""
from dataclasses import dataclass, field
